function validate([nums, goal]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 40) return 'nums needs 1 to 40 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -10000000 || v > 10000000)) return 'Each value is an integer from -10^7 to 10^7.';
  if (!Number.isInteger(goal) || goal < -1000000000 || goal > 1000000000) return 'goal is an integer from -10^9 to 10^9.';
  return null;
}

