function minAbsDifference(nums, goal) {
  const sumsOf = (part) => {
    const sums = new Float64Array(1 << part.length);
    for (let k = 0; k < part.length; k++) {
      const size = 1 << k;
      for (let mask = 0; mask < size; mask++) {
        sums[size + mask] = sums[mask] + part[k];
      }
    }
    return sums.sort();
  };
  const half = Math.floor(nums.length / 2);
  const left = sumsOf(nums.slice(0, half));
  const right = sumsOf(nums.slice(half));
  let best = Math.abs(goal);
  let i = 0;
  let j = right.length - 1;
  while (i < left.length && j >= 0) {
    const sum = left[i] + right[j];
    best = Math.min(best, Math.abs(sum - goal));
    if (sum < goal) {
      i++;
    } else if (sum > goal) {
      j--;
    } else {
      return 0;
    }
  }
  return best;
}

