function minAbsDifference(nums, goal) {
  let answer = Infinity;
  const walk = (index, total) => {
    if (index === nums.length) {
      answer = Math.min(answer, Math.abs(total - goal));
      return;
    }
    walk(index + 1, total);
    walk(index + 1, total + nums[index]);
  };
  walk(0, 0);
  return answer;
