  if (mode < 0.3) {
    // A goal that some subsequence hits exactly.
    goal = nums.reduce((acc, v) => (rand() < 0.5 ? acc + v : acc), 0);
  } else if (mode < 0.65) {
    // Near a reachable total but slightly off.
    goal = nums.reduce((acc, v) => (rand() < 0.5 ? acc + v : acc), 0) + Math.floor(rand() * 21) - 10;
  } else if (mode < 0.85) {
    goal = Math.floor(rand() * (2 * span * n + 1)) - span * n;
